require_once __DIR__ . '/../includes/auth.php'; require_login(); $id=(int)($_GET['id']??$_POST['pedido_id']??0);$order=order_by_id($id);if(!can_access_order($order)){http_response_code(404);exit('Pedido não encontrado.');}
if(is_post()){
  validate_csrf($_POST['csrf_token']??null);$action=(string)($_POST['action']??'');$user=current_user();
  try{$pdo=db();$pdo->beginTransaction();
    if($action==='observation'){ $text=trim((string)($_POST['texto']??''));if(mb_strlen($text)<2)throw new RuntimeException('Escreva uma observação antes de salvar.');$pdo->prepare('INSERT INTO pedido_observacoes (pedido_id,usuario_id,texto) VALUES (?,?,?)')->execute([$id,$user['id'],$text]);$pdo->prepare('INSERT INTO pedido_historico (pedido_id,usuario_id,acao,descricao) VALUES (?, ?, "observacao", "Observação interna adicionada.")')->execute([$id,$user['id']]);$pdo->commit();notify_role('administrador','Nova observação',$order['numero'].' recebeu uma observação.','producao/detalhes.php?id='.$id);if($order['responsavel_id'])notify_user((int)$order['responsavel_id'],'Nova observação',$order['numero'].' recebeu uma observação.','producao/detalhes.php?id='.$id);audit('adicionou_observacao','pedido',$id);flash('success','Observação adicionada.'); }
    elseif($action==='remove_file'){$fileId=(int)($_POST['arquivo_id']??0);$s=$pdo->prepare('SELECT * FROM pedido_arquivos WHERE id=? AND pedido_id=? AND removido_em IS NULL');$s->execute([$fileId,$id]);$file=$s->fetch();if(!$file)throw new RuntimeException('Anexo não encontrado.');$pdo->prepare('UPDATE pedido_arquivos SET removido_em=NOW(),removido_por_id=? WHERE id=?')->execute([$user['id'],$fileId]);$pdo->prepare('INSERT INTO pedido_historico (pedido_id,usuario_id,acao,descricao) VALUES (?, ?, "remocao_anexo", ?)')->execute([$id,$user['id'],'Anexo removido logicamente: '.$file['nome_original']]);$pdo->commit();audit('removeu_anexo','pedido',$id,['arquivo'=>$file['nome_original']],['arquivo_id'=>$fileId]);flash('success','Anexo removido do pedido.');}
    elseif($action==='finalize'){if($order['etapa']!=='pronto')throw new RuntimeException('Somente pedidos prontos podem ser finalizados.');$pdo->prepare('UPDATE pedidos SET etapa="finalizado",finalizado_em=NOW(),etapa_atualizada_em=NOW() WHERE id=?')->execute([$id]);$pdo->prepare('INSERT INTO pedido_etapas_historico (pedido_id,etapa_anterior,etapa_nova,usuario_id) VALUES (?,?,"finalizado",?)')->execute([$id,'pronto',$user['id']]);$pdo->prepare('INSERT INTO pedido_historico (pedido_id,usuario_id,acao,descricao) VALUES (?, ?, "finalizacao", "Pedido entregue/finalizado.")')->execute([$id,$user['id']]);$pdo->commit();notify_role('administrador','Pedido finalizado',$order['numero'].' foi finalizado.','producao/detalhes.php?id='.$id);audit('finalizacao','pedido',$id,['etapa'=>'pronto'],['etapa'=>'finalizado']);flash('success','Pedido finalizado com sucesso.');}
    elseif($action==='cancel'){if($order['etapa']==='cancelado')throw new RuntimeException('Este pedido já está cancelado.');$pdo->prepare('UPDATE pedidos SET etapa="cancelado",cancelado_em=NOW(),cancelado_por_id=?,etapa_atualizada_em=NOW() WHERE id=?')->execute([$user['id'],$id]);$pdo->prepare('INSERT INTO pedido_etapas_historico (pedido_id,etapa_anterior,etapa_nova,usuario_id) VALUES (?,?,"cancelado",?)')->execute([$id,$order['etapa'],$user['id']]);$pdo->prepare('INSERT INTO pedido_historico (pedido_id,usuario_id,acao,descricao) VALUES (?, ?, "cancelamento", "Pedido cancelado.")')->execute([$id,$user['id']]);$pdo->commit();notify_role('administrador','Pedido cancelado',$order['numero'].' foi cancelado.','producao/detalhes.php?id='.$id);audit('cancelamento','pedido',$id,['etapa'=>$order['etapa']],['etapa'=>'cancelado']);flash('success','Pedido cancelado.');}
    elseif($action==='restore'){if(!is_admin()||$order['etapa']!=='cancelado')throw new RuntimeException('Ação não permitida.');$pdo->prepare('UPDATE pedidos SET etapa="novo",cancelado_em=NULL,cancelado_por_id=NULL,etapa_atualizada_em=NOW() WHERE id=?')->execute([$id]);$pdo->prepare('INSERT INTO pedido_etapas_historico (pedido_id,etapa_anterior,etapa_nova,usuario_id) VALUES (?,"cancelado","novo",?)')->execute([$id,$user['id']]);$pdo->prepare('INSERT INTO pedido_historico (pedido_id,usuario_id,acao,descricao) VALUES (?, ?, "restauracao", "Pedido restaurado para Pedido novo.")')->execute([$id,$user['id']]);$pdo->commit();audit('restauracao','pedido',$id,['etapa'=>'cancelado'],['etapa'=>'novo']);flash('success','Pedido restaurado.');}
    else throw new RuntimeException('Ação inválida.');
  }catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();error_log('Detalhes pedido: '.$e->getMessage());flash('error',$e instanceof RuntimeException?$e->getMessage():'Não foi possível concluir a ação.');}
  redirect('producao/detalhes.php?id='.$id);
}
$page_title='Pedido '.$order['numero'];require_once __DIR__ . '/../includes/header.php';$order=order_by_id($id);$filesStmt=db()->prepare('SELECT * FROM pedido_arquivos WHERE pedido_id=? AND removido_em IS NULL ORDER BY created_at DESC');$filesStmt->execute([$id]);$files=$filesStmt->fetchAll();$hist=db()->prepare('SELECT h.*,u.nome FROM pedido_historico h LEFT JOIN usuarios u ON u.id=h.usuario_id WHERE h.pedido_id=? ORDER BY h.created_at DESC');$hist->execute([$id]);$history=$hist->fetchAll();$obs=db()->prepare('SELECT o.*,u.nome FROM pedido_observacoes o JOIN usuarios u ON u.id=o.usuario_id WHERE o.pedido_id=? ORDER BY o.created_at DESC');$obs->execute([$id]);$observations=$obs->fetchAll();$users=is_admin()?db()->query('SELECT id,nome FROM usuarios WHERE ativo=1 ORDER BY nome')->fetchAll():[];$stageOrder=['novo','preparacao','producao','pronto'];$current=array_search($order['etapa'],$stageOrder,true);
