ect name="responsavel_id"><option value="">Não definido</option><?php foreach($users as $u):?><option value="<?=$u['id']?>" <?=$order['responsavel_id']==$u['id']?'selected':''?>><?=e($u['nome'])?></option><?php endforeach;?></select></label><?php endif;?><label class="full">Observações internas<textarea name="observacoes_internas"><?=e($order['observacoes_internas'])?></textarea></label><label class="full">Adicionar anexos<input type="file" name="arquivos[]" multiple accept=".pdf,.png,.jpg,.jpeg,.webp,.svg,.cdr,.ai,.eps,.psd,.tiff,.zip"></label></div><div class="form-actions"><button class="btn btn-primary" type="submit">Salvar alterações</button></div></form></section>
